def rot90_clockwise(cells):
    # For a 4x4 cell grid, rotate 90 degrees clockwise
    new_cells = {}
    for cr in range(4):
        for cc in range(4):
            new_cc = 3 - cr  # Column becomes (4 - row - 1)
            new_cr = cc  # Row becomes old column
            new_cells[(new_cr, new_cc)] = cells[(cr, cc)]
    return new_cells

def rot270_clockwise(cells):
    new_cells = {}
    for cr in range(4):
        for cc in range(4):
            new_cc = cc
            new_cr = 3 - cr
            new_cells[(new_cr, new_cc)] = cells[(cr, cc)]
    return new_cells

def rot180(cells):
    new_cells = {}
    for cr in range(4):
        for cc in range(4):
            new_cells[(3-cr, 3-cc)] = cells[(cr, cc)]
    return new_cells

